<script lang="ts">
import {auth}from '#lib/auth.svelte.ts';import {anyApi}from 'convex/server';
let report=$state<any>(null),file=$state<File|null>(null),consent=$state(false),busy=$state(false),message=$state('');
$effect(()=>{const c=auth.client;if(!c)return;return c.onUpdate(anyApi.tennisShadow.summary,{},r=>report=r,()=>message='Tennis shadow status could not load.');});
async function upload(e:SubmitEvent){e.preventDefault();if(!file||!consent)return;busy=true;message='';try{if(file.size>8*1024*1024)throw Error('Use a dataset smaller than 8 MB.');const response=await fetch('/api/admin/tennis',{method:'POST',headers:{'Content-Type':'application/json'},body:await file.text()});if(!response.ok)throw Error(await response.text());message='Dataset queued for daily offline training and evaluation. Point-stat models remain in shadow.';}catch(e){message=(e as Error).message;}finally{busy=false;}}
</script>
<section class="surface min-w-0 p-5 sm:p-6"><div class="flex flex-wrap items-center justify-between gap-3"><h2 class="text-xl font-bold">🎾 Tennis model laboratory</h2><span class="rounded-full bg-raised px-3 py-2 text-xs font-bold">Point-stat models in shadow</span></div><p class="mt-3 text-sm text-haze">Results-based estimates are available in the <a href="/tennis" class="font-semibold text-model underline">experimental tennis workspace</a>. Automatic tennis settlement and verified-value approval remain unavailable.</p><p class="mt-3 text-sm text-haze">{report?.status??'Loading protected training status…'}</p>{#if report?.at}<p class="mt-2 text-xs text-haze">Last evaluation: {new Date(report.at).toLocaleString('en-NG',{timeZone:'Africa/Lagos'})} WAT</p>{/if}<dl class="mt-4 grid grid-cols-2 gap-3 text-sm sm:grid-cols-4"><div><dt class="text-xs text-haze">History rows</dt><dd class="mt-1 font-bold">{report?.rows??0}</dd></div><div><dt class="text-xs text-haze">Competitions found</dt><dd class="mt-1 font-bold">{report?.coverage?.competitions??'—'}</dd></div><div><dt class="text-xs text-haze">Discovered fixtures</dt><dd class="mt-1 font-bold">{report?.coverage?.fixtures??'—'}</dd></div><div><dt class="text-xs text-haze">Discovery credits</dt><dd class="mt-1 font-bold">{report?.coverage?.chargedCredits??'—'}</dd></div></dl>
<details class="mt-4 rounded-xl border border-line p-3"><summary class="min-h-9 cursor-pointer text-sm font-semibold">Calibration & evaluation evidence</summary><p class="mt-2 text-xs text-haze">{report?.policy??'Chronological point-stat fitting and held-out calibration evaluation. Missing data never becomes a published forecast.'}</p>{#each report?.markets??[] as market}<div class="mt-3 rounded-xl bg-ink p-3 text-xs"><strong>{market.tour??''} · {market.market.replaceAll('_',' ')}</strong><p class="mt-1">Calibration samples {market.calibrationRows} · Held-out matches {market.raw.n}</p><p class="mt-1">Brier {market.raw.brier?.toFixed(4)??'Unavailable'} · Log loss {market.raw.logLoss?.toFixed(4)??'Unavailable'}</p><p class="mt-1">{market.evaluationSufficient?'Evaluation sample threshold met; betting approval remains separate.':'Insufficient evaluation evidence.'}</p></div>{:else}<p class="mt-3 text-xs text-haze">No measured tennis performance is available yet.</p>{/each}{#each report?.reasons??[] as reason}<p class="mt-2 text-xs text-loss">{reason}</p>{/each}</details>
<details class="mt-4 rounded-xl border border-line p-3"><summary class="min-h-9 cursor-pointer text-sm font-semibold">Historical research benchmark · not live validation</summary><p class="mt-2 text-xs text-haze">{report?.research?.split??'No research benchmark recorded yet.'}</p>{#each report?.research?.segments??[] as segment}<p class="mt-3 text-xs">{segment.sex} · {segment.market} · Training {segment.trainingMatches} · Calibration {segment.calibrationMatches} · Test {segment.test.n} · Brier {segment.test.brier?.toFixed(4)??'Unavailable'}</p>{/each}{#each report?.research?.limitations??[] as reason}<p class="mt-2 text-xs text-haze">{reason}</p>{/each}<p class="mt-3 text-xs text-haze">Source: Jauhari, Morankar &amp; Fokoue (2014), UCI Tennis Major Tournament Match Statistics, CC BY 4.0, DOI 10.24432/C54C7K.</p></details>
<details class="mt-4 rounded-xl border border-line p-3"><summary class="min-h-9 cursor-pointer text-sm font-semibold">Results-only tennis challenger · 2021–2026</summary><p class="mt-3 text-xs text-haze">{report?.resultsResearch?.model??'Waiting for the results-only evaluation.'}</p><p class="mt-2 text-xs text-haze">{report?.resultsResearch?.split??''}</p><p class="mt-2 text-sm">Eligible completed matches: {report?.resultsResearch?.eligibleRows?.toLocaleString()??'—'}</p>{#each report?.resultsResearch?.segments??[] as segment}<div class="mt-3 rounded-xl bg-ink p-3 text-xs"><strong>{segment.tour} · {segment.market.replaceAll('_',' ')} · {segment.year}</strong><p class="mt-2">Test {segment.raw.n.toLocaleString()} · Calibration {segment.calibrationRows.toLocaleString()}</p><p class="mt-1">Raw Brier {segment.raw.brier?.toFixed(4)??'—'} · Calibrated {segment.calibrated?.brier?.toFixed(4)??'—'} · Accuracy {segment.calibrated?.accuracy!=null?(100*segment.calibrated.accuracy).toFixed(1)+'%':'Unavailable'}</p>{#if segment.openingOddsBenchmark?.n}<p class="mt-1">Same quoted subset: model Brier {segment.modelOnSameQuotedMatches?.brier?.toFixed(4)??'—'} · Opening-price benchmark {segment.openingOddsBenchmark.brier?.toFixed(4)??'—'} · n={segment.openingOddsBenchmark.n.toLocaleString()}</p>{/if}</div>{/each}{#each report?.resultsResearch?.limitations??[] as limitation}<p class="mt-2 text-xs text-haze">{limitation}</p>{/each}<p class="mt-3 text-xs text-haze">Source: <a class="underline" href="https://www.valuebetennis.com/donnees.htm" target="_blank" rel="noreferrer">Valuebetennis</a> · <a class="underline" href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. We normalize scores, exclude unsupported records, and fit ratings. No source endorsement is implied.</p></details>
<details class="mt-4 rounded-xl border border-line p-3"><summary class="min-h-9 cursor-pointer text-sm font-semibold">Upload licensed tennis point-stat history</summary><p class="mt-2 text-xs text-haze">JSON dataset, up to 5000 completed matches / 8 MB, with source and commercial-use license metadata. Raw history and fitted artifacts stay in private R2 storage. The daily training job evaluates them without calling paid sports APIs.</p><form class="mt-4 grid min-w-0 gap-3" onsubmit={upload}><label class="min-w-0 text-sm">Dataset JSON<input class="mt-2 block w-full min-w-0 text-xs" type="file" accept=".json,application/json" onchange={e=>file=e.currentTarget.files?.[0]??null}/></label><label class="flex items-start gap-2 text-xs text-haze"><input type="checkbox" bind:checked={consent}/>I confirm this dataset is licensed for this application and its source and license are recorded in the JSON.</label><button class="btn-primary" disabled={busy||!file||!consent}>{busy?'Uploading…':'Queue private training dataset'}</button></form></details>{#if message}<p role="status" class="mt-3 text-sm">{message}</p>{/if}</section>
